(function() {
  'use strict';

  const api = window.CardSpoke.utils;

  CardSpoke_MODS.register('developer-kit', {
    meta: {
      name: 'Developer Kit',
      type: 'Kit',
      version: '1.0.0',
      creator: 'CardSpoke',
      description: 'Comprehensive developer tools: syntax highlighting, code snippets, git integration, and API documentation'
    },

    STORAGE_KEY: 'developer-kit-data',
    codeSnippets: {},
    gitPanel: null,

    onAppInit(ctx) {
      ctx.logger.log('Developer Kit initialized');
      this.loadSnippets();
      this.createDevPanel(ctx);
      this.addKeyboardShortcuts(ctx);
    },

    loadSnippets() {
      try {
        const saved = localStorage.getItem(this.STORAGE_KEY);
        if (saved) {
          this.codeSnippets = JSON.parse(saved).snippets || {};
        }
      } catch (err) {
        console.error('Failed to load snippets:', err);
      }
    },

    saveSnippets() {
      try {
        localStorage.setItem(this.STORAGE_KEY, JSON.stringify({
          snippets: this.codeSnippets
        }));
      } catch (err) {
        console.error('Failed to save snippets:', err);
      }
    },

    createDevPanel(ctx) {
      this.gitPanel = document.createElement('div');
      this.gitPanel.id = 'developer-panel';
      this.gitPanel.innerHTML = `
        <div class="dev-panel-header">
          <span>👨‍💻 Developer Tools</span>
          <button class="dev-panel-minimize">−</button>
        </div>
        <div class="dev-panel-body">
          <div class="dev-panel-section">
            <h4>📝 Code Snippets</h4>
            <select class="snippet-language">
              <option value="javascript">JavaScript</option>
              <option value="python">Python</option>
              <option value="css">CSS</option>
              <option value="html">HTML</option>
              <option value="sql">SQL</option>
              <option value="bash">Bash</option>
            </select>
            <button class="insert-snippet-btn">Insert Snippet Template</button>
          </div>
          <div class="dev-panel-section">
            <h4>🔧 Quick Actions</h4>
            <button class="format-code-btn">Format Code in Card</button>
            <button class="extract-todos-btn">Extract TODOs</button>
            <button class="count-lines-btn">Count Lines of Code</button>
          </div>
          <div class="dev-panel-section">
            <h4>📊 Statistics</h4>
            <div class="dev-stats">
              <div>Code Cards: <span id="dev-code-cards">0</span></div>
              <div>Total LOC: <span id="dev-total-loc">0</span></div>
              <div>Languages: <span id="dev-languages">0</span></div>
            </div>
          </div>
        </div>
      `;

      document.body.appendChild(this.gitPanel);
      this.attachPanelListeners(ctx);
      this.updateStats(ctx);
    },

    attachPanelListeners(ctx) {
      const minimizeBtn = this.gitPanel.querySelector('.dev-panel-minimize');
      minimizeBtn.addEventListener('click', () => {
        this.gitPanel.classList.toggle('minimized');
      });

      const insertBtn = this.gitPanel.querySelector('.insert-snippet-btn');
      insertBtn.addEventListener('click', () => this.insertSnippet(ctx));

      const formatBtn = this.gitPanel.querySelector('.format-code-btn');
      formatBtn.addEventListener('click', () => this.formatCode(ctx));

      const todosBtn = this.gitPanel.querySelector('.extract-todos-btn');
      todosBtn.addEventListener('click', () => this.extractTodos(ctx));

      const countBtn = this.gitPanel.querySelector('.count-lines-btn');
      countBtn.addEventListener('click', () => this.countLinesOfCode(ctx));
    },

    addKeyboardShortcuts(ctx) {
      this.keyHandler = (e) => {
        // Ctrl+Shift+D: Toggle developer panel
        if ((e.ctrlKey || e.metaKey) && e.shiftKey && e.key === 'D') {
          e.preventDefault();
          this.gitPanel.classList.toggle('minimized');
        }
        // Ctrl+Shift+F: Format code
        if ((e.ctrlKey || e.metaKey) && e.shiftKey && e.key === 'F') {
          e.preventDefault();
          this.formatCode(ctx);
        }
      };
      document.addEventListener('keydown', this.keyHandler);
    },

    async insertSnippet(ctx) {
      const languageSelect = this.gitPanel.querySelector('.snippet-language');
      const language = languageSelect.value;

      const templates = {
        javascript: '```javascript\n// TODO: Add your code here\nfunction example() {\n  return "Hello World";\n}\n```',
        python: '```python\n# TODO: Add your code here\ndef example():\n    return "Hello World"\n```',
        css: '```css\n/* TODO: Add your styles here */\n.example {\n  color: blue;\n}\n```',
        html: '```html\n<!-- TODO: Add your markup here -->\n<div class="example">\n  Hello World\n</div>\n```',
        sql: '```sql\n-- TODO: Add your query here\nSELECT * FROM users WHERE active = true;\n```',
        bash: '```bash\n# TODO: Add your script here\necho "Hello World"\n```'
      };

      const template = templates[language];
      ctx.utils.showToast(`Copy this template:\n\n${template}`, 'info');

      // Try to copy to clipboard
      if (navigator.clipboard) {
        await navigator.clipboard.writeText(template);
        ctx.utils.showToast('Template copied to clipboard!', 'success');
      }
    },

    async formatCode(ctx) {
      ctx.utils.showToast('Code formatting is a placeholder - integrate with Prettier/beautify in production', 'info');
    },

    async extractTodos(ctx) {
      const allCards = Object.values(window.store?.cards || {});
      const todos = [];

      for (const card of allCards) {
        const matches = card.body.match(/\/\/\s*TODO:?\s*(.+)|#\s*TODO:?\s*(.+)/gi);
        if (matches) {
          todos.push({
            cardId: card.id,
            cardTitle: card.title,
            todos: matches
          });
        }
      }

      if (todos.length === 0) {
        ctx.utils.showToast('No TODOs found in code cards', 'info');
        return;
      }

      // Create summary
      const summary = todos.map(t => 
        `${t.cardTitle}:\n${t.todos.join('\n')}`
      ).join('\n\n');

      ctx.utils.showToast(`Found ${todos.length} cards with TODOs`, 'success');
      console.log('TODOs extracted:', summary);
    },

    async countLinesOfCode(ctx) {
      const allCards = Object.values(window.store?.cards || {});
      let totalLines = 0;
      let codeCards = 0;

      const codeBlockRegex = /```[\w]*\n([\s\S]*?)```/g;

      for (const card of allCards) {
        const matches = card.body.match(codeBlockRegex);
        if (matches) {
          codeCards++;
          matches.forEach(block => {
            const lines = block.split('\n').length - 2; // Exclude ``` lines
            totalLines += lines;
          });
        }
      }

      ctx.utils.showToast(
        `Found ${totalLines} lines of code across ${codeCards} cards`,
        'success'
      );

      this.updateStats(ctx);
    },

    updateStats(ctx) {
      const allCards = Object.values(window.store?.cards || {});
      let codeCards = 0;
      let totalLOC = 0;
      const languages = new Set();

      const codeBlockRegex = /```([\w]*)\n([\s\S]*?)```/g;

      for (const card of allCards) {
        let match;
        let hasCode = false;

        while ((match = codeBlockRegex.exec(card.body)) !== null) {
          hasCode = true;
          const lang = match[1] || 'plain';
          languages.add(lang);

          const lines = match[2].split('\n').length;
          totalLOC += lines;
        }

        if (hasCode) codeCards++;
      }

      if (this.gitPanel) {
        const codeCardsEl = this.gitPanel.querySelector('#dev-code-cards');
        const totalLOCEl = this.gitPanel.querySelector('#dev-total-loc');
        const languagesEl = this.gitPanel.querySelector('#dev-languages');

        if (codeCardsEl) codeCardsEl.textContent = codeCards;
        if (totalLOCEl) totalLOCEl.textContent = totalLOC;
        if (languagesEl) languagesEl.textContent = languages.size;
      }
    },

    onCardRender(ctx, card, element) {
      // Detect and highlight code blocks
      const bodyElement = element.querySelector('.card-body, .card-text, p');
      if (!bodyElement) return;

      let html = bodyElement.innerHTML;

      // Simple syntax highlighting for code blocks
      const codeBlockRegex = /```([\w]*)\n([\s\S]*?)```/g;
      html = html.replace(codeBlockRegex, (match, lang, code) => {
        const escapedCode = code
          .replace(/</g, '&lt;')
          .replace(/>/g, '&gt;');

        return `<div class="code-block-wrapper">
          <div class="code-block-header">
            <span class="code-language">${lang || 'plain'}</span>
            <button class="copy-code-btn" data-code="${escapedCode.replace(/"/g, '&quot;')}">📋 Copy</button>
          </div>
          <pre class="code-block language-${lang || 'plain'}"><code>${escapedCode}</code></pre>
        </div>`;
      });

      bodyElement.innerHTML = html;

      // Add copy functionality
      const copyButtons = bodyElement.querySelectorAll('.copy-code-btn');
      copyButtons.forEach(btn => {
        btn.addEventListener('click', async () => {
          const code = btn.dataset.code
            .replace(/&lt;/g, '<')
            .replace(/&gt;/g, '>')
            .replace(/&quot;/g, '"');

          if (navigator.clipboard) {
            await navigator.clipboard.writeText(code);
            ctx.utils.showToast('Code copied to clipboard!', 'success');
          }
        });
      });

      // Add language badge for code cards
      const hasCode = /<pre class="code-block/.test(html);
      if (hasCode) {
        element.classList.add('has-code');

        const codeBadge = document.createElement('span');
        codeBadge.className = 'code-card-badge';
        codeBadge.textContent = '</> Code';

        const titleElement = element.querySelector('.card-title');
        if (titleElement && !titleElement.querySelector('.code-card-badge')) {
          titleElement.appendChild(codeBadge);
        }
      }
    },

    async onCardSave(ctx, card, saveInfo) {
      // Update stats when cards are saved
      this.updateStats(ctx);

      // Auto-tag code cards
      const hasCode = /```[\w]*\n[\s\S]*?```/.test(card.body);
      if (hasCode && !card.tags.includes('code')) {
        await ctx.utils.addTag(card.id, 'code');
      }
    },

    onDisable(ctx) {
      if (this.gitPanel && this.gitPanel.parentNode) {
        this.gitPanel.parentNode.removeChild(this.gitPanel);
      }
      if (this.keyHandler) {
        document.removeEventListener('keydown', this.keyHandler);
      }
    },

    onUninstall(ctx) {
      if (confirm('Remove all Developer Kit data and snippets?')) {
        localStorage.removeItem(this.STORAGE_KEY);
      }
    }
  });
})();

