/* Developer Panel */
#developer-panel {
  position: fixed;
  top: 80px;
  left: 20px;
  width: 320px;
  background: var(--bg-alt);
  border: 2px solid var(--border);
  border-radius: 12px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.2);
  z-index: 10000;
}

#developer-panel.minimized .dev-panel-body {
  display: none;
}

.dev-panel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  border-radius: 10px 10px 0 0;
  font-weight: bold;
}

.dev-panel-minimize {
  background: rgba(255, 255, 255, 0.2);
  border: none;
  color: white;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  cursor: pointer;
}

.dev-panel-body {
  padding: 16px;
  max-height: 500px;
  overflow-y: auto;
}

.dev-panel-section {
  margin-bottom: 20px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--border);
}

.dev-panel-section:last-child {
  border-bottom: none;
  margin-bottom: 0;
}

.dev-panel-section h4 {
  margin: 0 0 12px 0;
  font-size: 0.9em;
  color: var(--text-primary);
}

.dev-panel-section button,
.dev-panel-section select {
  width: 100%;
  margin-bottom: 8px;
  padding: 8px;
  border: 1px solid var(--border);
  background: var(--bg-primary);
  color: var(--text-primary);
  border-radius: 6px;
  cursor: pointer;
  font-size: 0.85em;
}

.dev-panel-section button:hover {
  background: var(--accent);
  color: white;
  border-color: var(--accent);
}

.dev-stats {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 0.85em;
}

.dev-stats span {
  font-weight: bold;
  color: #667eea;
}

/* Code blocks */
.code-block-wrapper {
  margin: 12px 0;
  border: 1px solid var(--border);
  border-radius: 8px;
  overflow: hidden;
}

.code-block-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 12px;
  background: var(--bg-hover);
  border-bottom: 1px solid var(--border);
}

.code-language {
  font-size: 0.75em;
  font-weight: bold;
  text-transform: uppercase;
  color: var(--accent);
}

.copy-code-btn {
  padding: 4px 8px;
  font-size: 0.75em;
  background: var(--accent);
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;
}

.copy-code-btn:hover {
  opacity: 0.8;
}

.code-block {
  margin: 0;
  padding: 12px;
  background: #282c34;
  color: #abb2bf;
  font-family: 'Courier New', monospace;
  font-size: 0.85em;
  line-height: 1.5;
  overflow-x: auto;
}

.code-block code {
  background: none;
  padding: 0;
  border: none;
}

/* Code card badge */
.code-card-badge {
  display: inline-block;
  margin-left: 8px;
  padding: 2px 8px;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  border-radius: 12px;
  font-size: 0.7em;
  font-weight: bold;
}

/* Syntax highlighting colors */
.language-javascript .code-block,
.language-js .code-block {
  background: #282c34;
}

.language-python .code-block {
  background: #2b2b2b;
}

.language-css .code-block {
  background: #1e1e1e;
}

.language-html .code-block {
  background: #1e1e1e;
}
